import{_ as a,a0 as o,w as u,s,ao as l,I as r,x as n,a1 as e,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何拥有一个 Windows 10 和 Debian 10 的双系统 | LCTT x X-CMD","titleTemplate":false,"description":"如何拥有一个 Windows 10 和 Debian 10 的双系统 | LCTT (201911) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何拥有一个 Windows 10 和 Debian 10 的双系统 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何拥有一个 Windows 10 和 Debian 10 的双系统 | LCTT (201911) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201911/20191023 How to dual boot Windows 10 and Debian 10","title":"如何拥有一个 Windows 10 和 Debian 10 的双系统","tag":"201911","desc":""},"relativePath":"201911/20191023 How to dual boot Windows 10 and Debian 10.md","filePath":"[post].md"}'),w={name:"201911/20191023 How to dual boot Windows 10 and Debian 10.md"};function b(c,t,d,m,g,h){const i=o("Link");return u(),s("div",null,[t[15]||(t[15]=l('<h1 id="如何拥有一个-windows-10-和-debian-10-的双系统" tabindex="-1">如何拥有一个 Windows 10 和 Debian 10 的双系统 <a class="header-anchor" href="#如何拥有一个-windows-10-和-debian-10-的双系统" aria-label="Permalink to “如何拥有一个 Windows 10 和 Debian 10 的双系统”">​</a></h1><p>在无数次劝说自己后，你终于做出了一个大胆的决定，试试 Linux。不过，在完全熟悉 Linux 之前，你依旧需要使用 Windows 10 系统。幸运的是，通过一个双系统引导设置，能让你在启动时，选择自己想要进入的系统。在这个指南中，你会看到如何 如何双重引导 Windows 10 和 Debian 10。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/How-to-dual-boot-Windows-and-Debian10.jpg" alt="如何拥有一个 Windows 10 和 Debian 10 的双系统"></p><h3 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to “前提条件”">​</a></h3><p>在开始之前，确保你满足下列条件:</p><ul><li>一个 Debian 10 的可引导 USB 或 DVD</li><li>一个快速且稳定的网络（为了安装更新以及第三方软件）</li></ul><p>另外，记得注意你系统的引导策略（UEFI 或 Legacy），需要确保两个系统使用同一种引导模式。</p><h3 id="第一步-在硬盘上创建一个空余分区" tabindex="-1">第一步：在硬盘上创建一个空余分区 <a class="header-anchor" href="#第一步-在硬盘上创建一个空余分区" aria-label="Permalink to “第一步：在硬盘上创建一个空余分区”">​</a></h3><p>第一步，你需要在你的硬盘上创建一个空余分区。之后，这将是我们安装 Debian 系统的地方。为了实现这一目的，需要使用下图所示的磁盘管理器：</p><p>同时按下 <code>Windows + R</code> 键，启动“运行程序”。接下来，输入 <code>diskmgmt.msc</code>，按回车键。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Launch-Run-dialogue.jpg" alt="启动“运行程序”"></p><p>这会启动“磁盘管理”窗口，它会显示你 Windows 上所有已有磁盘。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Disk-management.jpg" alt="磁盘管理"></p><p>接下来，你需要为安装的 Debian 系统创建空余空间。为此，你需要缩小其中一个磁盘（卷）上的分区，从而创建一个未分配的新分区。在这个例子里，我会从 D 盘中创建一个 30 GB 的新分区。</p><p>为了缩小一个卷，右键点击它，然后选中选项 “<ruby>缩小<rt>Shrink volume...</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Shrink-volume.jpg" alt="缩小卷"></p><p>在弹出窗口中，定义你想缩小的空间大小。记住，这是将来要安装 Debian 10 的磁盘空间。我选择了 30000MB（大约 30 GB）。压缩完成后，点击“<ruby>缩小<rt>Shrink</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Shrink-space.jpg" alt="缩小空间"></p><p>在缩小操作结束后，你会看到一个如下图所示的未分配分区：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Unallocated-partition.jpg" alt="未分配分区"></p><p>完美！现在可以准备开始安装了。</p><h3 id="第二步-开始安装-debian-10" tabindex="-1">第二步：开始安装 Debian 10 <a class="header-anchor" href="#第二步-开始安装-debian-10" aria-label="Permalink to “第二步：开始安装 Debian 10”">​</a></h3><p>空余分区已经创建好了，将你的可引导 USB 或安装 DVD 插入电脑，重新启动系统。记得更改 BIOS 中的引导顺序，需要在启动时按住功能键（通常，根据品牌不同，是 <code>F9</code>、<code>F10</code> 或 <code>F12</code> 中的某一个）。 这一步骤，对系统是否能进入安装媒体来说，至关重要。保存 BIOS 设置，并重启电脑。</p><p>如下图所示，界面会显示一个新的引导菜单：点击 “Graphical install”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Graphical-Install-Debian10.jpg" alt="图形化界面安装"></p><p>下一步，选择你的偏好语言，然后点击 “<ruby>继续<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Select-Language-Debian10.jpg" alt="设置语言-Debian10"></p><p>接着，选择你的地区，点击“<ruby>继续<rt>Continue</rt></ruby>”。 根据地区，系统会自动选择当地对应的时区。如果你无法找到你所对应的地区，将界面往下拉， 点击“<ruby>其他<rt>Other</rt></ruby>”后，选择相对应位置。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Select-location-Debain10.jpg" alt="选择地区-Debain10"></p><p>而后，选择你的键盘布局。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Configure-Keyboard-layout-Debain10.jpg" alt="设置键盘-Debain10"></p><p>接下来，设置系统的主机名，点击 “<ruby>继续<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Set-hostname-Debian10.jpg" alt="设置主机名-Debian10"></p><p>下一步，确定域名。如果你的电脑不在域中，直接点击 “<ruby>继续<rt>Continue</rt></ruby>”按钮。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Set-domain-name-Debian10.jpg" alt="设置域名-Debian10"></p><p>然后，如图所示，设置 root 密码，点击 “<ruby>继续<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Set-root-Password-Debian10.jpg" alt="设置 root 密码-Debian10"></p><p>下一步骤，设置账户的用户全名，点击 “<ruby>继续<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Specify-fullname-user-debain10.jpg" alt="设置用户全名-debain10"></p><p>接着，设置与此账户相关联的用户名。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Specify-username-Debian10.jpg" alt="指定用户名-Debian10"></p><p>下一步，设置用户密码，点击“<ruby>继续<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Specify-user-password-Debian10.jpg" alt="设置用户密码-Debian10"></p><p>然后，设置时区。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Configure-timezone-Debian10.jpg" alt="设置时区-Debian10"></p><p>这时，你要为 Debian10 安装创建分区。如果你是新手用户，点击菜单中的第一个选项，“<ruby>使用最大的连续空余空间<rt>Use the largest continuous free space</rt></ruby>”，点击“<ruby>继续<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Use-largest-continuous-free-space-debian10.jpg" alt="使用最大的连续空余空间-debian10"></p><p>不过，如果你对创建分区有所了解的话，选择“<ruby>手动<rt>Manual</rt></ruby>” 选项，点击 “<ruby>继续<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Select-Manual-Debain10.jpg" alt="选择手动-Debain10"></p><p>接着，选择被标记为 “<ruby>空余空间<rt>FREE SPACE</rt></ruby>” 的磁盘，点击 “<ruby>继续<rt>Continue</rt></ruby>” 。接下来，点击“<ruby>创建新分区<rt>Create a new partition</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Create-new-partition-Debain10.jpg" alt="创建新分区-Debain10"></p><p>下一界面，首先确定交换空间大小。我的交换空间大小为 2GB，点击 “<ruby>继续<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Define-swap-space-debian10.jpg" alt="确定交换空间大小-debian10"></p><p>点击下一界面的 “<ruby>主分区<rt>Primary</rt></ruby>”，点击“<ruby>继续<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Partition-Disks-Primary-Debain10.jpg" alt="磁盘主分区-Debian10"></p><p>选择在磁盘 “<ruby>初始位置<rt>beginning</rt></ruby>” 创建新分区后，点击继续。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Start-at-the-beginning-Debain10.jpg" alt="在初始位置创建-Debain10"></p><p>选择 “<ruby>Ext 4 日志文件系统<rt>Ext 4 journaling file system</rt></ruby>”，点击 “<ruby>继续<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Select-Ext4-Journaling-system-debain10.jpg" alt="选择 Ext4 日志文件系统-debain10"></p><p>下个界面选择“<ruby>交换空间<rt>swap space</rt></ruby>” ，点击 “<ruby>继续<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Select-swap-debain10.jpg" alt="选择交换空间-debian10"></p><p>选中 “<ruby>完成此分区设置<rt>done setting the partition</rt></ruby>”，点击 “<ruby>继续<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Done-setting-partition-debian10.jpg" alt="完成此分区设置-debian10"></p><p>返回磁盘分区界面，点击 “<ruby>空余空间<rt>FREE SPACE</rt></ruby>”，点击 “<ruby>继续<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Click-Free-space-Debain10.jpg" alt="点击空余空间-Debain10"></p><p>为了让自己能轻松一点，选中 “<ruby>自动为空余空间分区<rt>Automatically partition the free space</rt></ruby>”后，点击 “<ruby>继续<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Automatically-partition-free-space-Debain10.jpg" alt="自动为空余空间分区-Debain10"></p><p>接着点击 “<ruby>将所有文件存储在同一分区（新手用户推荐）<rt>All files in one partition (recommended for new users)</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/All-files-in-one-partition-debian10.jpg" alt="将所有文件存储在同一分区-debian10"></p><p>最后， 点击 “<ruby>完成分区设置，并将改动写入磁盘<rt>Finish partitioning and write changes to disk</rt></ruby>” ，点击 “<ruby>继续<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Finish-partitioning-write-changes-to-disk.jpg" alt="完成分区设置，并将改动写入磁盘"></p><p>确定你要将改动写入磁盘，点击 “<ruby>是<rt>Yes</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Write-changes-to-disk-Yes-Debian10.jpg" alt="将改动写入磁盘-Debian10"></p><p>而后，安装程序会开始安装所有必要的软件包。</p><p>当系统询问是否要扫描其他 CD 时，选择 “<ruby>否<rt>No</rt></ruby>” ，并点击 “<ruby>继续<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Scan-another-CD-No-Debain10.jpg" alt="扫描其他CD-No-Debain10"></p><p>接着，选择离你最近的镜像站点地区，点击 “<ruby>继续<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Debian-archive-mirror-country.jpg" alt="Debian-镜像站点-国家"></p><p>然后，选择最适合你的镜像站点，点击“<ruby>继续<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Select-Debian-archive-mirror.jpg" alt="选择镜像站点"></p><p>如果你打算使用代理服务器，在下面输入具体信息，没有的话就留空，点击 “<ruby>继续<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Enter-proxy-details-debian10.jpg" alt="输入代理信息-debian10"></p><p>随着安装进程的继续， 你会被问到，是否想参加一个软件包用途调查。你可以选择任意一个选项，之后点击“<ruby>继续<rt>Continue</rt></ruby>”，我选择了“<ruby>否<rt>No</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Participate-in-survey-debain10.jpg" alt="参与调查-debain10"></p><p>在软件选择窗口选中你想安装的软件包，点击“<ruby>继续<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Software-selection-debian10.jpg" alt="软件选择-debian10"></p><p>安装程序会将选中的软件一一安装，在这期间，你可以去喝杯咖啡休息一下。</p><p>系统将会询问你，是否要将 grub 的引导装载程序安装到主引导记录表（MBR）上。点击 “<ruby>是<rt>Yes</rt></ruby>”，而后点击 “<ruby>继续<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Install-grub-bootloader-debian10.jpg" alt="安装-grub-bootloader-debian10"></p><p>接着，选中你想安装 grub 的硬盘，点击“<ruby>继续<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Select-hard-drive-install-grub-Debian10.jpg" alt="选择硬盘-安装 grub-Debian10"></p><p>最后，安装完成，直接点击 “<ruby>继续<rt>Continue</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Installation-complete-reboot-debian10.jpg" alt="安装完成-重新启动-debian10"></p><p>你现在应该会有一个列出 Windows 和 Debian 的 grub 菜单。为了引导 Debian 系统，往下选择 Debian。之后，你就能看见登录界面。输入密码之后，按回车键。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Debian10-log-in.jpg" alt="Debian10-登录"></p><p>这就完成了！这样，你就拥有了一个全新的 Debian 10 和 Windows 10 双系统。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/10/Debian10-Buster-Details.jpg" alt="Debian10-Buster-Details"></p><hr>',98)),r("p",null,[t[1]||(t[1]=n("via: ",-1)),e(i,{href:"https://www.linuxtechi.com/dual-boot-windows-10-debian-10/"},{default:p(()=>[...t[0]||(t[0]=[n("https://www.linuxtechi.com/dual-boot-windows-10-debian-10/",-1)])]),_:1})]),r("p",null,[t[6]||(t[6]=n("作者：",-1)),e(i,{href:"https://www.linuxtechi.com/author/james/"},{default:p(()=>[...t[2]||(t[2]=[n("James Kiarie",-1)])]),_:1}),t[7]||(t[7]=n(" 选题：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:p(()=>[...t[3]||(t[3]=[n("lujun9972",-1)])]),_:1}),t[8]||(t[8]=n(" 译者：",-1)),e(i,{href:"https://github.com/wenwensnow"},{default:p(()=>[...t[4]||(t[4]=[n("wenwensnow",-1)])]),_:1}),t[9]||(t[9]=n(" 校对：",-1)),e(i,{href:"https://github.com/wxy"},{default:p(()=>[...t[5]||(t[5]=[n("wxy",-1)])]),_:1})]),r("p",null,[t[12]||(t[12]=n("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[10]||(t[10]=[n("LCTT",-1)])]),_:1}),t[13]||(t[13]=n(" 原创编译，",-1)),e(i,{href:"https://linux.cn/"},{default:p(()=>[...t[11]||(t[11]=[n("Linux中国",-1)])]),_:1}),t[14]||(t[14]=n(" 荣誉推出",-1))])])}const C=a(w,[["render",b]]);export{x as __pageData,C as default};
